/* TNM World Wrestling Report: AJPW (All Japan Pro Wrestling).
   Everything the site shows for this promotion lives in this file. */

P.ajpw = {"short": "AJPW", "name": "All Japan Pro Wrestling", "home": "Tokyo", "c": "var(--ajpw)", "asOf": "1991-07-15", "status": "Eight nights in, and Toshiaki Kawada is gone. On his last night the Miracle Violence Connection took the World Tag titles from him and Misawa, and he walked out alone. Jumbo kept the Triple Crown against Kobashi, and Williams gets him at Budokan.", "stat": ["$695,257", "gate, first 8 nights"], "titles": [["Triple Crown", "Jumbo Tsuruta", "Retained vs. Kobashi (Okayama 7/15). Vs. Steve Williams at Budokan 7/27."], ["World Tag Team", "Miracle Violence Connection", "Williams & Gordy won the belts from Misawa & Kawada in Okayama 7/15, Kawada's last date. Vs. Misawa & Kobashi in Yokohama 7/23."], ["All Asia Tag Team", "Can-Am Express", "Furnas & Kroffat. Lost a non-title match to the Fantastics in Okayama 7/15; defend against them at Budokan."], ["World Junior", "To confirm", "Slinger and Fuchi won #1 contenders matches on opening night."]], "factions": [["Super Generation", "Mitsuharu Misawa and Kenta Kobashi. Toshiaki Kawada left after losing the World Tag titles in Okayama 7/15."], ["Miracle Violence Connection", "Steve Williams & Terry Gordy. World Tag Team Champions since 7/15. Williams gets Jumbo at Budokan."], ["The Foreign Heels", "Abdullah the Butcher, Giant Kimala II and Rick Rude, with Stan Hansen siding with them in Sendai."], ["The Malenkos", "Dean and Joe, self-appointed gatekeepers of the junior division."], ["The British Bulldogs", "Davey Boy Smith & Dynamite Kid, the top foreign draw."]], "stories": [["Kawada Walks Out", "Toshiaki Kawada's last AJPW date was Okayama on 7/15. Gordy powerbombed him to take the World Tag titles for the Miracle Violence Connection, and Kawada walked to the back alone. The dressing room says he's headed to New Japan."], ["Super Generation Answers Jumbo", "Misawa pinned Gordy with the Tiger Driver in Hiroshima, two nights after Jumbo's team beat the same three men. Williams pointed at the Triple Crown poster. Jumbo answered: Budokan is on, Kobashi first. In Okayama Jumbo kept the Triple Crown against Kobashi, who kicked out of the knee twice."], ["The Fall of the Giant", "Abdullah's fork put Giant Baba on a stretcher in Chiba. Out about 12 cards. Baba wants Misawa vs. Abdullah, Texas Death, at Budokan."], ["Misawa Rising", "A ****1/4 win over Dory Funk Jr., a tag title defense in Nagoya, and the hottest feud of the summer with Abdullah."], ["The Gatekeepers", "The Malenkos have declared themselves the wall every young junior has to climb. Kikuchi keeps trying. Ogawa got over it once."], ["Tag Team Logjam", "Can-Am Express, Miracle Violence, the Bulldogs, the Fantastics, Hansen & Spivey and Kobashi & Taue are all fighting for the same spot."], ["Ravishing, Briefly", "Rick Rude came to Japan as a star. So far he has a win over a 49-year-old, an upset loss to Bobby Fulton and a lot of airline miles."]], "desk": ["Kawada left after Okayama 7/15 (lost the World Tag titles to MVC). Rumored NJPW. Paid per appearance: 6 nights.", "Okayama 7/15: 2,100 at $20 ($42,000), onesheet figures. Smallest gate of the tour, best card (***3/4).", "Jumbo vs. Kobashi ran as a Triple Crown defense in the sim.", "Dean Malenko interfered against Ogawa 7/15 (unplanned); Ogawa still won.", "Hiroshima 7/13: 3,800 at $25 ($95,000), onesheet figures. ****3/4 six-man, the best match of the tour; Inoue vs. Travis ****1/4 in the opener.", "Joe Malenko interfered against Rusher Kimura in the Abdullah tag. The Malenkos with the foreign heels?", "Nagoya 7/11: 6,000 at $32 ($192,000), the best average ticket of the tour, plus $12,000 merchandise.", "Booking conflict: Abdullah wrestled WCW Columbus 7/8 and AJPW Kanazawa 7/9.", "Budokan main event changed: announced as Misawa vs. Jumbo on night 1, now Williams vs. Jumbo, with Misawa vs. Abdullah (Texas Death) as Baba wants.", "Baba out ~12 cards, so the plan's Baba matches (Kumamoto 7/17, Sapporo 7/21) are gone.", "Eigen hurt his elbow 7/9. Back at Kumamoto 7/17.", "Ace no-showed 7/5. Ogawa no-showed 7/5.", "Dean Malenko has run out of junior challengers after beating Ace 2–0. Next contender needed before Budokan."], "roster": [["Jumbo Tsuruta", "40 · Triple Crown Champion"], ["Giant Baba", "INJ:53 · neck, out ~12 cards"], ["Mitsuharu Misawa", "29 · Super Generation"], ["Kenta Kobashi", "24 · Super Generation"], ["Akira Taue", "30"], ["Haruka Eigen", "INJ:45 · elbow, back 7/17"], ["Stan Hansen", "41 · also USWA"], ["Terry Gordy", "30 · Miracle Violence, World Tag Champ"], ["Steve Williams", "31 · Miracle Violence, World Tag Champ"], ["Dan Spivey", "38 · also USWA"], ["Dory Funk Jr.", "50"], ["Doug Furnas", "31 · Can-Am, All Asia Tag Champ"], ["Dan Kroffat", "30 · Can-Am, All Asia Tag Champ"], ["Bobby Fulton", "30 · Fantastics"], ["Tommy Rogers", "30 · Fantastics"], ["Davey Boy Smith", "British Bulldogs"], ["Dynamite Kid", "32 · British Bulldogs"], ["Dean Malenko", "30"], ["Joe Malenko", "35"], ["Johnny Ace", "29"], ["Masanobu Fuchi", "38"], ["Yoshinari Ogawa", "24"], ["Tsuyoshi Kikuchi", "26"], ["Masao Inoue", "21"], ["Richard Slinger", "22"], ["Too Cold Scorpio", ""], ["Billy Joe Travis", ""], ["Rusher Kimura", "55"], ["Giant Kimala II", "31"], ["Abdullah the Butcher", "50 · also WCW"], ["Rick Rude", "32 · also WCW"]], "departures": [["Toshiaki Kawada", "Left after Okayama 7/15, where he and Misawa lost the World Tag titles. Rumored NJPW."]]};

E.push(...[{"d": "1991-07-01", "p": "ajpw", "city": "Tokyo", "venue": "Korakuen Hall", "type": "Summer Action Series, Night 1", "gate": "1,750 · $51,992", "rate": "*1/4", "link": "SUMMER_A", "m": [["#1 contenders: Richard Slinger vs. Joe Malenko", "Slinger (Chattanooga Choo Choo)", "***"], ["#1 contenders: Masanobu Fuchi vs. Giant Kimala II", "Fuchi (backdrop suplex)", "*1/4"], ["Rick Rude vs. Rusher Kimura", "Rude (Rude Awakening)", "**1/2"], ["All Asia Tag: Can-Am Express vs. Fantastics", "Can-Am retain. Furnas pins Fulton", "**3/4"], ["British Bulldogs vs. Miracle Violence Connection (No DQ)", "Bulldogs. Davey pins Gordy", "**"], ["Match Without Honor: Giant Baba vs. Abdullah", "Baba (running neckbreaker)", "-**1/2"], ["Super Generation vs. Jumbo, Taue & Eigen", "20:00 draw", "**1/2"]], "n": ["Baba: a new generation wants him to retire, and he won't go quietly.", "Budokan 7/27 announced: Misawa vs. Jumbo for the Triple Crown."]}, {"d": "1991-07-03", "p": "ajpw", "city": "Chiba", "venue": "Port Arena", "type": "Night 2", "gate": "2,315 · $71,765", "rate": "3/4*", "link": "CHIBA__C", "m": [["#1 contenders: Joe Malenko vs. Tsuyoshi Kikuchi", "Joe (Final Lesson)", "3/4*"], ["Can-Am Express vs. Fantastics", "Kroffat pins Fulton (Tiger Driver)", "**1/2"], ["Williams, Gordy & Hansen vs. Taue, Ogawa & Dory Funk Jr.", "Hansen pins Funk (lariat)", "***"], ["No count-out: Abdullah vs. Giant Baba", "Abdullah by DQ. Baba stretchered out", "-****1/4"], ["Triple Crown: Jumbo Tsuruta vs. Toshiaki Kawada", "Jumbo retains (Jumbo Knee)", "***"]], "n": ["Giant Baba injured (neck) by Abdullah's fork. Out about 12 cards."]}, {"d": "1991-07-05", "p": "ajpw", "city": "Sendai", "venue": "City Gym", "type": "Night 3", "gate": "3,500 · $87,500", "rate": "**3/4", "link": "SENDI__S", "m": [["Too Cold Scorpio vs. Billy Joe Travis", "Scorpio (Scorpio Splash)", "*3/4"], ["Taue & Kobashi vs. British Bulldogs", "Kobashi pins Davey (flying legdrop)", "***1/4"], ["Bobby Fulton vs. Rick Rude", "Fulton (dropkick). Upset", "**3/4"], ["Rogers & Inoue vs. Slinger & Kikuchi", "Rogers (sleeper on Slinger)", "***1/2"], ["Abdullah, Kimala II & Hansen vs. Misawa, Funk & Fuchi", "Abdullah pins Misawa", "*3/4"], ["All Asia Tag: Miracle Violence vs. Can-Am Express", "Double count-out. Can-Am retain", "**3/4"]]}, {"d": "1991-07-07", "p": "ajpw", "city": "Niigata", "venue": "City Gym", "type": "Night 4", "gate": "2,700 · $67,500", "rate": "***1/4", "link": "NIGATA__", "m": [["Too Cold Scorpio vs. Richard Slinger", "Scorpio (Scorpio Splash)", "**1/2"], ["Terry Gordy vs. Giant Kimala II", "Gordy by DQ", "1/2*"], ["Ogawa, Inoue & Rogers vs. Can-Am Express & Johnny Ace", "Ogawa pins Kroffat", "**1/4"], ["Kenta Kobashi vs. Billy Joe Travis", "Kobashi (lariat)", ""], ["British Bulldogs vs. Fuchi & Kikuchi", "Dynamite pins Kikuchi (headbutt)", "***3/4"], ["Malenkos vs. Kawada & Kikuchi", "Dean (Texas Cloverleaf on Kikuchi)", "***3/4"], ["Mitsuharu Misawa vs. Dory Funk Jr.", "Misawa (running elbow)", "****1/4"]]}, {"d": "1991-07-09", "p": "ajpw", "city": "Kanazawa", "venue": "Ishikawa Gym", "type": "Night 5 (Nippon TV)", "gate": "3,500 · $87,500", "rate": "***1/2", "link": "KANAZAWA", "m": [["Haruka Eigen vs. Masao Inoue", "Eigen. Hurts elbow", "**"], ["Fantastics vs. Hansen & Spivey", "Rogers rolls up Spivey. Upset", "**1/2"], ["Johnny Ace vs. Too Cold Scorpio", "Ace (Implant DDT). Scorpio's first loss", "***1/2"], ["All Asia Tag: Can-Am Express vs. Kobashi & Taue", "Can-Am retain (Tiger Driver on Taue)", "****1/4"], ["Bulldogs & Misawa vs. Rude, Abdullah & Kimala II", "Misawa pins Kimala II", "**3/4"], ["Steve Williams vs. Toshiaki Kawada", "Williams (Oklahoma Stampede)", "****"]], "n": ["Williams calls out Jumbo. Jumbo comes to the ring, silent. Face-off.", "Baba reportedly wants Misawa vs. Abdullah, Texas Death, at Budokan."]}, {"d": "1991-07-11", "p": "ajpw", "city": "Nagoya", "venue": "Aichi Prefectural Gymnasium", "type": "Night 6", "rate": "***1/4", "link": "NAGOYA__", "m": [["Too Cold Scorpio vs. Rusher Kimura", "Scorpio (Scorpio Splash)", "**3/4"], ["Jumbo, Taue & Kobashi vs. Williams, Gordy & Slinger", "Jumbo pins Slinger (Jumbo Knee)", "***"], ["2 of 3 falls: Dean Malenko vs. Johnny Ace", "Dean, 2–0 (side suplex 31:31; count-out 37:17)", "***1/2"], ["All Asia Tag: Can-Am Express vs. Ogawa & Inoue", "Can-Am retain. Kroffat pins Ogawa", "***1/4"], ["Hansen & Spivey vs. British Bulldogs", "Double count-out", "***"], ["World Tag: Misawa & Kawada vs. Rude & Abdullah", "Misawa & Kawada retain. Misawa pins Rude", "***1/2"]], "gate": "6,000 · $192,000", "n": ["Merchandise: $12,000, about $2 a head. First AJPW merch figure logged.", "Unannounced six-man added: Jumbo pins Slinger.", "Hansen & Spivey vs. Bulldogs brawl past the bell."]}, {"d": "1991-07-13", "p": "ajpw", "city": "Hiroshima", "venue": "Hiroshima Sun Plaza", "type": "Six-man tag special", "m": [["Masao Inoue vs. Billy Joe Travis", "Inoue (roll-up)", "****1/4"], ["Too Cold Scorpio vs. Johnny Ace", "Scorpio (Flying Scorpio Splash)", "****"], ["Kimura & Fuchi vs. Abdullah & Kimala II", "Kimura & Fuchi by DQ. Joe Malenko interferes; Abdullah's fork", "DUD"], ["Funk & the Malenkos vs. Ogawa, Kikuchi & Taue", "Joe makes Kikuchi submit (Final Lesson). Match of the tour", "****3/4"], ["British Bulldogs vs. Fantastics", "Dynamite pins Fulton (diving headbutt)", "***"], ["Interview: Jumbo Tsuruta answers Williams", "Budokan is on, Kobashi first", ""], ["Misawa, Kawada & Kobashi vs. Williams, Gordy & Slinger", "Misawa pins Gordy (Tiger Driver). Williams points at the Triple Crown poster", "***"]], "gate": "3,800 · $95,000", "rate": "***", "n": ["Attendance and gate from the AJPW onesheet. No merchandise reported.", "Toshiaki Kawada gave notice after the show.", "Hansen & Spivey worked USWA Louisville; Rude was in WCW Greenville."], "link": "HIROSHIM"}, {"d": "1991-07-15", "p": "ajpw", "city": "Okayama", "venue": "Okayama Budokan", "type": "Night 8 · Kawada's last AJPW date", "m": [["Kikuchi & Inoue vs. Slinger & Travis", "Kikuchi pins Slinger (bridging back suplex), 11:59", "****1/4"], ["Dynamite Kid vs. Too Cold Scorpio", "Dynamite (diving headbutt), 12:17", "****1/4"], ["Akira Taue vs. Davey Boy Smith", "Taue (nodowa otoshi), 10:16", "***1/4"], ["Yoshinari Ogawa vs. Joe Malenko", "Ogawa (small package), 15:26. Dean Malenko interferes; no handshake", "***"], ["Can-Am Express vs. Fantastics (non-title)", "Rogers rolls up Kroffat, 17:53. Fantastics earn the Budokan shot", "***"], ["Triple Crown: Jumbo Tsuruta (c) vs. Kenta Kobashi", "Jumbo retains (backdrop driver), 18:55. Kobashi survives the knee", "****1/4"], ["World Tag: Misawa & Kawada (c) vs. Miracle Violence Connection", "MVC win the titles. Gordy powerbombs Kawada, 20:21. Kawada leaves alone", "****"]], "n": ["Toshiaki Kawada's last AJPW date. Rumored to be headed to New Japan.", "2,100 at $20 ($42,000), onesheet figures. Capacity 3,000. No merchandise reported.", "Jumbo vs. Kobashi ran as a Triple Crown defense.", "Dean Malenko interfered against Ogawa (unplanned). Ogawa won anyway.", "Rested: Abdullah, Kimala II, Fuchi, Kimura, Funk, Ace."], "ran": 1, "gate": "2,100 · $42,000", "rate": "***3/4"}, {"d": "1991-07-17", "p": "ajpw", "city": "Kumamoto", "venue": "Prefectural Gym", "type": "Southern loop", "m": [["Misawa vs. Stan Hansen", "Misawa (Tiger Driver)", ""], ["Kenta Kobashi vs. Rick Rude", "Kobashi (moonsault). Misawa names Kobashi his new partner", ""]], "n": ["Eigen returns. Baba's planned tag is off (injured).", "Kobashi replaces Kawada against Rude."]}, {"d": "1991-07-19", "p": "ajpw", "city": "Fukuoka", "venue": "Sports Center", "type": "Southern showcase", "m": [["Miracle Violence Connection vs. Fantastics (non-title)", "MVC", ""]]}, {"d": "1991-07-21", "p": "ajpw", "city": "Sapporo", "venue": "Nakajima Sports Center", "type": "Northern swing (original plan)", "m": [["Misawa & Jumbo vs. Hansen & Gordy", "Misawa pins Hansen", ""]], "n": ["Baba vs. Rude is off (Baba injured)."]}, {"d": "1991-07-23", "p": "ajpw", "city": "Yokohama", "venue": "Cultural Gym", "type": "Pre-finale", "m": [["World Tag: MVC (c) vs. Misawa & Kobashi", "MVC retain. Williams pins Kobashi (Doctor Bomb)", ""]], "n": ["Replaces Misawa vs. Kawada."]}, {"d": "1991-07-25", "p": "ajpw", "city": "Osaka", "venue": "Prefectural Gym", "type": "Co-main event", "m": [["Jumbo vs. Stan Hansen", "Jumbo", ""], ["Misawa & Kobashi vs. MVC (non-title)", "Misawa pins Gordy; earns a fall title shot", ""]]}, {"d": "1991-07-27", "p": "ajpw", "city": "Tokyo", "venue": "Nippon Budokan", "type": "Summer Action Series finale", "big": 1, "m": [["Triple Crown: Jumbo Tsuruta vs. Steve Williams", "Jumbo (two backdrop drivers)", ""], ["All Asia Tag: Can-Am Express vs. Fantastics", "Can-Am retain (Kroffat pins Fulton)", ""], ["Texas Death: Misawa vs. Abdullah", "Misawa, revenge for Baba", ""], ["Kenta Kobashi vs. Davey Boy Smith", "Kobashi. Davey Boy's last AJPW date", ""], ["Junior elimination: Kikuchi, Ogawa, Slinger, Inoue", "Ogawa", ""], ["Rick Rude vs. Johnny Ace", "Rude", ""]]}]);

Object.assign(ARTICLES, {"ajpw-kawada-last-date": {"p": "ajpw", "news": 1, "by": "Newsletter staff", "date": "1991-07-13", "region": "Japan Report", "kicker": "AJPW · Backstage", "title": "Kawada's Last Memphis Date", "dek": "Toshiaki Kawada turned down Paul Ellering, got laid out for it, and has one USWA date left on his deal. All Japan wants him home for good.", "body": [["p", "Toshiaki Kawada's USWA run has been short and strange. He came in on a small deal, turned down Paul Ellering's offer to join his stable, and was attacked and laid out on the June 29 build for Star Wars. Ellering said on TV in Memphis on July 6 that Kawada is not joining him. That was the last anyone in the USWA has heard of him."], ["p", "Kawada has one card left on the USWA deal. In Japan, he's one of the Super Generation alongside Misawa and Kobashi, he went to a strong finish with Jumbo Tsuruta for the Triple Crown in Chiba, and he and Misawa are the All Japan World Tag Team Champions after retaining against Rick Rude and Abdullah in Nagoya on July 11."], ["h", "What happens next"], ["p", "The expectation is that All Japan doesn't let him go back. Baba is hurt, Misawa is the hottest thing in the building and Kawada is his partner. If the USWA wants to use the last date, the best version is a one-off revenge match with whoever Ellering sent after him in June. Otherwise, the Kawada story in Memphis ends where it started: as a man who said no."]], "facts": [["USWA cards left", "1"], ["Turned down", "Paul Ellering"], ["AJPW", "Super Generation; World Tag Team Champion with Misawa"], ["Last defense", "vs. Rude & Abdullah, Nagoya 7/11"]], "factTitle": "Kawada"}, "ajpw-fall-of-the-giant": {"p": "ajpw", "kicker": "All Japan · Summer Action Series · Chiba, July 3", "title": "The Fall of the Giant", "dek": "Giant Baba went on a stretcher, the Chiba crowd went silent, and the tour finale at Budokan got rebuilt around one man's revenge.", "by": "Japan report", "date": "1991-07-11", "body": [["p", "The biggest story in All Japan right now isn't a match. It's a stretcher."], ["p", "At Chiba Port Arena on July 3 (2,315 paid, $71,765, which is about what you'd expect for a weeknight warm-up show), Giant Baba and Abdullah the Butcher went 20:50 in a no count-out match. That was way too long for two guys whose combined age is 103, and it got the rating it deserved: minus four and a quarter stars. Nobody was there for the workrate. They got the angle instead."], ["p", "Abdullah went to the fork, as he has for about 25 years, and this time went right for Baba's neck. Johnny Ace, who was working Baba's corner, shoved Abdullah off, and referee Joe Higuchi called for the bell to give Baba the DQ. Then the paramedics came in. Baba was stretchered out to an ambulance with the crowd watching in what the Japanese press described as stunned silence. The storyline is a neck injury that keeps him out about 12 cards."], ["p", "The timing is what makes it work. Two nights earlier at Korakuen, Baba beat Abdullah in a \"Match Without Honor\" (-**1/2, if you're keeping score) and then got on the mic. A new generation of stars wanted him to step aside and retire, he said, and he wasn't going quietly. Only he would decide when he was done. The crowd chanted his name. Forty-eight hours later he's in the back of an ambulance. You don't have to be a genius to see where this is headed."], ["h", "The Budokan question"], ["p", "Here's where it gets interesting. On opening night, All Japan announced Misawa challenging Jumbo for the Triple Crown as the Budokan main event on July 27. Since then Steve Williams has called out Jumbo (more on that elsewhere), and the word is that Baba, from the sidelines, wants Misawa vs. Abdullah in a Texas Death Match on the same show. Misawa beat Abdullah's partner Kimala II in Kanazawa and pinned Rude with Abdullah standing on the apron in Nagoya. Every one of those finishes has been booked to read as a message."], ["p", "It's a smart switch if that's where it lands. Misawa vs. Jumbo is a match you only get to do for the first time once, and it may be worth more in the fall. Misawa getting revenge for the boss in a gimmick match makes him the man who stood up for Baba, which in All Japan is about the biggest thing you can be short of champion. And Abdullah, who can't go 20 minutes without the match being a disaster, is protected by the stipulation."], ["h", "The fine print"], ["p", "Baba was pleased with the crowds, even though nothing has sold out. Eigen hurt his elbow in Kanazawa, so the old guard is thin. Rusher Kimura is 55 and Dory Funk is 50. With Baba out, the undercard leans on the juniors and the foreigners for a few weeks. That might not be the worst thing in the world."]], "facts": [["Date", "Wed, July 3, 1991"], ["Venue", "Chiba Port Arena"], ["Crowd", "2,315 · $71,765"], ["Match", "Abdullah d. Baba (DQ), 20:50"], ["Rating", "-****1/4"], ["Injury", "Baba, neck, ~12 cards"]], "factTitle": "The Damage"}, "ajpw-dr-death-wants-jumbo": {"p": "ajpw", "kicker": "All Japan · Kanazawa, July 9", "title": "Dr. Death Wants Jumbo", "dek": "Steve Williams doesn't talk much. In Kanazawa he grabbed the microphone, called out the Triple Crown champion, and got a stare back.", "by": "Japan report", "date": "1991-07-11", "body": [["p", "Steve Williams vs. Toshiaki Kawada in Kanazawa on July 9 was the match that changed the tour. It got the TV time on Nippon TV and it deserved it, at four stars on a ***1/2 card that drew 3,500 for $87,500."], ["p", "It was built the right way. Kawada threw everything he had: the kicks, the suplexes, the elbows. Williams just took it, kept coming forward and finally put him away with the Oklahoma Stampede, clean, at 16:14. That's two big singles losses on the tour for Kawada, who also lost to Jumbo in Chiba. In both of them he got the crowd behind him and lost anyway. That's how All Japan makes a guy, and he'll be fine. But for now, he's the measuring stick."], ["h", "The callout"], ["p", "Then Williams did something he almost never does and took the microphone. Jumbo is the champion, he said, but he's the strongest man in the company, and Jumbo is next. Jumbo walked to the ring in silence and the two of them stood nose to nose while the place went nuts. Not one word from Jumbo. Which, if you know Jumbo, is exactly right."], ["p", "So the Budokan picture has a new top line: Jumbo vs. Dr. Death for the Triple Crown. That would replace the opening-night announcement of Jumbo vs. Misawa, and it frees Misawa for the Baba revenge story. From a booking standpoint it's the safer play. Williams is a big, credible foreign challenger who can lose to Jumbo without being hurt by it, and you save Misawa vs. Jumbo for when the business can really pop for it."], ["h", "The champion"], ["p", "Jumbo has done almost nothing wrong on this tour. He beat Kawada with the Jumbo Knee in 9:13 in Chiba, which was the right length for a title match in a building that size. In Nagoya he teamed with Taue and Kobashi to beat Williams, Gordy and Slinger, and the booking was telling: Jumbo pinned Slinger and never had to beat Williams directly. You don't give away the money match on a house show."], ["p", "Miracle Violence Connection have been the hardest-working team on the tour. They lost to the Bulldogs on opening night (No DQ, Bulldog pinned Gordy) and had a double count-out war with the Can-Am Express in Sendai. Williams has a reason to be a singles guy for a couple of weeks. Expect Gordy to be the one holding the tag team spot down while his partner chases Jumbo."]], "facts": [["Date", "Tue, July 9, 1991"], ["Venue", "Ishikawa Gym, Kanazawa"], ["Crowd", "3,500 · $87,500"], ["Result", "Williams d. Kawada, 16:14"], ["Finish", "Oklahoma Stampede"], ["Rating", "****"]], "factTitle": "The Match"}, "ajpw-misawa-rising": {"p": "ajpw", "kicker": "All Japan · The Super Generation", "title": "Misawa Rising", "dek": "Six nights in, Mitsuharu Misawa has had the best match of the tour, kept the tag belts and found himself a feud. The torch hasn't been passed. The arm is in motion.", "by": "Japan report", "date": "1991-07-11", "body": [["p", "If there's one reason to be excited about All Japan right now, it's Mitsuharu Misawa."], ["p", "The Super Generation (Misawa, Kobashi and Kawada) were the story of opening night at Korakuen: a 20:00 draw with Jumbo, Taue and Eigen in a six-man that got **1/2. That was fine but not special. The concept matters more than the match. Kawada is back from his USWA excursion (where he worked with Bret Hart, Bill Dundee and Scotty Flamingo), and the three of them are positioned, very openly, as the generation coming for Jumbo."], ["h", "The Niigata match"], ["p", "The match of the tour so far is Misawa vs. Dory Funk Jr. in Niigata on July 7, at ****1/4. It was an old-school, deliberate main event. Misawa let Funk set the pace and work on him, then picked it up with the elbows and finished with the running elbowsmash at 20:27. Management is calling it an \"education bout,\" which is All Japan-speak for putting the young ace in with the old master so everyone can see he belongs. It worked. The Niigata crowd (2,700, not a sellout) went home happy."], ["p", "Then the losses came, and they were booked to mean something. In Sendai, Abdullah, Kimala II and Hansen beat Misawa, Funk and Fuchi when Abdullah pinned Misawa with a back elbow. That's about as much as Abdullah can do at this point, but it gave Misawa a reason. In Kanazawa he got some back, pinning Kimala II in a six-man with the Bulldogs. And in Nagoya on July 11, Misawa and Kawada kept the World Tag Team Championship over Rude and Abdullah. Misawa pinned Rude with the elbowsmash at 23:11. That rated ***1/2, and it's the most anyone has gotten out of Abdullah in a while."], ["h", "The Kobashi factor"], ["p", "The Super Generation's third man has had quietly the best tour of anyone in it. Kobashi and Taue beat the British Bulldogs in Sendai (Kobashi pinned Davey Boy with a flying legdrop, ***1/4). He got the Burning Lariat squash in Niigata, then had the best match of the Kanazawa card before the main event: a ****1/4 loss with Taue to the Can-Am Express that got all four guys a standing ovation. He also apparently walked out on a two-on-one Bulldogs attack in Niigata, which nobody has explained yet."], ["p", "Kawada is the one taking the losses right now, to Jumbo and to Williams, and that's normal for the third guy in a group like this. He's also holding half the tag titles. Nobody here is suffering."], ["p", "The torch isn't passed. Jumbo is still the man. But Misawa has the hottest feud on the tour, the best match on the tour and the Budokan special attraction if the Texas Death Match happens. Six weeks ago that would have been a lot to ask."]], "facts": [["Best match", "d. Dory Funk Jr., ****1/4 (7/7)"], ["Titles", "World Tag Champion w/ Kawada"], ["Defense", "d. Rude & Abdullah (7/11), ***1/2"], ["Losses", "Six-man in Sendai (7/5)"], ["Next", "Abdullah, Texas Death? (Budokan)"]], "factTitle": "Misawa's Tour"}, "ajpw-the-gatekeepers": {"p": "ajpw", "kicker": "All Japan · Junior Division", "title": "The Gatekeepers", "dek": "Dean and Joe Malenko have appointed themselves the wall every young junior heavyweight has to climb. So far only one man has gotten over it, and it wasn't the one working the hardest.", "by": "Japan report", "date": "1991-07-11", "body": [["p", "The most interesting thing happening on All Japan undercards is a story Baba seems to really like: the Malenko brothers as gatekeepers of the junior division. It fits the technical style he wants in his midcard, and it gives a group of young guys something to do besides lose."], ["p", "The pattern has been clear. Joe Malenko made Tsuyoshi Kikuchi submit to the Final Lesson in Chiba (3/4*, short and nothing special). Then in Niigata the Malenkos pushed their way into a match with Kawada and Kikuchi, bullying the referee into starting it, and Dean put Kikuchi in the Texas Cloverleaf for the submission at 17:34. That one went ***3/4 and was the talk of the locker room. Kawada brought the stiffness, the Malenkos brought the precision, and Kikuchi got beat up like he does every night and kept coming back, which is the whole point of Kikuchi."], ["p", "Nagoya was Dean's showcase: a two-out-of-three falls match with Johnny Ace that went 37 minutes and change. Dean took the first fall with a side suplex at 31:31 and the second by count-out. A two-falls-to-none finish after half an hour is a bold way to book it. It rated ***1/2, and it established Dean as a guy you're not going to beat by just being younger and fresher."], ["h", "The ones knocking"], ["p", "Kikuchi has lost to Joe, lost with Kawada to both Malenkos, and taken a Dynamite Kid flying headbutt for the pin in Niigata. He's the junior the crowd is most behind and the one who has won the least. That's a story with a finish built in."], ["p", "Yoshinari Ogawa is the one who has broken through, sort of. In Niigata he pinned Dan Kroffat of the All Asia champion Can-Am Express with a backdrop suplex hold, which earned him and Masao Inoue a title shot in Nagoya. They lost (Kroffat pinned Ogawa with a moonsault bodyblock, ***1/4). But a pinfall over a champion is a pinfall over a champion. Ogawa no-showed Sendai, which isn't helping his case."], ["p", "Too Cold Scorpio went unbeaten for the first four nights with the Flying Scorpio Splash before Johnny Ace beat him clean with the Implant DDT in Kanazawa (***1/2). Staff see Scorpio as a future star if he stays consistent. Ace has had a strange tour: he worked Baba's corner in Chiba, no-showed Sendai, beat Scorpio and then went 37 minutes with Dean."], ["p", "Opening night also had two number-one contenders matches, Richard Slinger over Joe Malenko (***) and Masanobu Fuchi over Kimala II. Number one for what hasn't been made clear. Somebody should probably tell the fans."]], "facts": [["Joe d. Kikuchi", "Chiba 7/3 · 3/4*"], ["Malenkos d. Kawada & Kikuchi", "Niigata 7/7 · ***3/4"], ["Dean d. Ace, 2–0", "Nagoya 7/11 · ***1/2"], ["Ace d. Scorpio", "Kanazawa 7/9 · ***1/2"], ["Ogawa pins Kroffat", "Niigata 7/7"]], "factTitle": "The Junior Ledger"}, "ajpw-tag-team-logjam": {"p": "ajpw", "kicker": "All Japan · Tag Team Division", "title": "Tag Team Logjam", "dek": "Six good teams, two sets of belts and a lot of double count-outs. The Can-Am Express keep winning, and nobody else can get a clean finish.", "by": "Japan report", "date": "1991-07-11", "body": [["p", "The All Japan tag division is so deep right now that the problem is finishes. Too many good teams, too few belts, and a promotion that hates having anybody lose clean."], ["p", "The Can-Am Express (Doug Furnas and Dan Kroffat) are the All Asia champions and have been the busiest team on the tour. They beat the Fantastics on opening night (Furnas's dragon suplex on Fulton, **3/4) and again in Chiba (Kroffat's Tiger Driver, **1/2). They went to a 23-minute double count-out with Miracle Violence in Sendai. They beat Kobashi and Taue in Kanazawa in the best match of that card (****1/4, standing ovation for all four). And they beat Ogawa and Inoue in Nagoya. That's four title defenses and a draw in six nights. These guys are carrying a lot of the undercard."], ["h", "Everyone else"], ["p", "Miracle Violence Connection (Williams and Gordy) lost the No DQ match to the Bulldogs on opening night and haven't been beaten since in tag action, but they haven't won a tag match clean either. With Williams chasing Jumbo, they're going to be split for a while."], ["p", "The British Bulldogs are the top foreign draw on the tour. They beat MVC, they beat Fuchi and Kikuchi (***3/4), and they had a double count-out with Hansen and Spivey in Nagoya. They also lost to Kobashi and Taue in Sendai. Some staff are worried about how much longer Dynamite Kid's body will hold up, and you can see why."], ["p", "The Fantastics ended a losing streak with the upset of the tour so far: Tommy Rogers rolled up Dan Spivey in Kanazawa to beat Spivey and Hansen. Hansen tore up the ringside area afterward. Bobby Fulton also pinned Rick Rude with a dropkick in Sendai, so the Fantastics are suddenly 2–0 in big spots after losing to Can-Am twice."], ["p", "Hansen and Spivey are still splitting time with the USWA. They have a loss and a double count-out."], ["h", "Where it goes"], ["p", "The World Tag titles belong to Misawa and Kawada, and they don't appear to be in danger from this group yet. The original Budokan plan had Kobashi and Kawada challenging Can-Am for the All Asia belts, which makes a lot of sense given how good the Kanazawa match was. If they want a clean finish somewhere on this tour, that's the place."]], "facts": [["All Asia Champs", "Can-Am Express"], ["World Tag Champs", "Misawa & Kawada"], ["Best tag match", "Can-Am d. Kobashi & Taue, ****1/4"], ["Biggest upset", "Fantastics d. Hansen & Spivey"], ["Double count-outs", "2"]], "factTitle": "The Standings"}, "ajpw-ravishing-briefly": {"p": "ajpw", "kicker": "All Japan · Foreign Talent", "title": "Ravishing, Briefly", "dek": "Rick Rude is commuting across the Pacific to work two promotions at once. In All Japan, at least, it doesn't look like it's been worth the miles.", "by": "Japan report", "date": "1991-07-11", "body": [["p", "Rick Rude is one of the hottest heels in WCW, and he's working the All Japan tour at the same time, flying back to the States for Richmond on July 7 and headed back again for Greenville and the Great American Bash. In Japan, things haven't gone the way he's used to."], ["p", "Opening night was fine. He pinned 55-year-old Rusher Kimura with the Rude Awakening in 10:30 (**1/2). Then in Sendai on July 5 he was supposed to face Johnny Ace, who no-showed, and ended up with Bobby Fulton instead. Rude went in irritated and overconfident, made one mistake, and Fulton beat him with a dropkick at 18:21. A dropkick. The Sendai crowd went crazy for it and Rude stormed to the back."], ["p", "He flew to Richmond, beat Dustin Rhodes by count-out with Paul E. Dangerously's help, and came back for Kanazawa, where he, Abdullah and Kimala II lost a six-man to the Bulldogs and Misawa. In Nagoya he and Abdullah challenged Misawa and Kawada for the World Tag titles, and Misawa pinned him with the elbowsmash. Officially that's 1–3 in Japan."], ["h", "Why it might be fine"], ["p", "There are two ways to read it. The pessimistic one is that All Japan is using an expensive American as an opponent for its native stars, and Rude's stock in Japan is going down. The optimistic one is that this is exactly what a foreign heel is for. Misawa pinning a big-name American star on a title defense is how you build Misawa, and Rude's heat in WCW doesn't depend on his record in Nagoya."], ["p", "The bigger issue is the travel. Abdullah, his tag partner, appears to have wrestled WCW in Columbus, Georgia on July 8 and All Japan in Kanazawa on July 9, which isn't a thing anyone can actually do. Somebody at one of these promotions needs to look at a calendar. In Rude's case the remaining All Japan plan has him beating Kawada in Kumamoto on July 17, after Greenville on the 13th and the Bash on the 14th. He'll be tired. He might also finally get a win."]], "facts": [["7/1 Korakuen", "W · d. Rusher Kimura"], ["7/5 Sendai", "L · to Bobby Fulton (dropkick)"], ["7/7 WCW Richmond", "W · d. Dustin Rhodes (count-out)"], ["7/9 Kanazawa", "L · six-man"], ["7/11 Nagoya", "L · World Tag Title match"], ["AJPW record", "1–3"]], "factTitle": "Rude's Itinerary"}, "ajpw-observer-nagoya-0711": {"p": "ajpw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-11", "region": "Tokyo Report", "kicker": "AJPW · Aichi Prefectural Gymnasium, July 11", "title": "Nagoya: $32 a Seat and Both Belts Stay Put", "dek": "Misawa pins Rude, Ogawa loses and wins the crowd again, and a six-man nobody announced gets Jumbo on the card.", "factTitle": "Match observations", "facts": [["Venue", "Aichi Prefectural Gymnasium"], ["City", "Nagoya, Japan"], ["Date", "July 11, 1991 (Summer Action Series, Night 6)"], ["Attendance", "6,000"], ["Average ticket", "$32.00"], ["Gate", "$192,000.00"], ["Merchandise", "$12,000.00 ($2.00 per fan)"], ["Card", "***1/4"]], "body": [["p", "Night 6 of the Summer Action Series carried a card rating of ***1/4, right in line with the tour's usual range, but the story of Nagoya is how much of the card went to form. Both titles stayed put, the plan's two gaijin tag teams fought to a no-decision, and the only real swerve was a six-man nobody had announced going in."], ["p", "Misawa and Kawada's World Tag Team defense against Rude and Abdullah went 23:11 and earned ***1/2, the best match of the night. Misawa ending it with the Running Elbowsmash on Rude, not Abdullah, is worth noting. Rude has been the house's measuring stick all tour, and beating him clean means more right now than putting away Abdullah would have. Kawada took the worst of it (Abdullah's usual aisle-brawling), which keeps the sympathy on the champions without putting either one in real jeopardy."], ["p", "The All Asia Tag Title match (Ogawa & Inoue vs. Furnas & Kroffat, 16:06, ***1/4) continues to be the best story on this tour that isn't happening at the top. Ogawa has lost every one of these defenses and somehow looks like the biggest winner on the card every time. Whoever is driving the booking here is sitting on a hot ticket for whenever this pays off."], ["p", "The Jumbo Tsuruta/Akira Taue/Kenta Kobashi vs. Miracle Violence Connection & Richard Slinger six-man (10:29, ***) wasn't on any schedule that circulated before the tour, and it reads like a late add to get Jumbo on the card without touching the Williams program. Jumbo pinning Slinger instead of either MVC man protects Williams and Gordy completely while still letting the Triple Crown champion look sharp. Slinger, for his part, is now 0 for his last several in programs with the top of the roster — somebody in the production truck clearly trusts him to take a loss and make it mean something."], ["p", "Dean Malenko's 2-out-of-3 falls win over Johnny Ace (31:31/37:17, split by a side suplex and a countout, ***1/2) was a step up in stipulation from what was planned, and it worked. The Malenkos have run out of believable AJPW challengers; if this is the end of that run, it's a strong note to end it on."], ["p", "The rest: - Too Cold Scorpio d. Rusher Kimura, Flying Scorpio Splash, 10:37, **3/4. Professional, unremarkable opener. - Stan Hansen & Dan Spivey vs. British Bulldogs (Davey Boy Smith & Dynamite Kid), double countout, 18:38, ***. No finish doesn't mean no heat — this one ran past the bell. Worth watching whether this becomes a program or stays a one-off."], ["p", "Business: 6,000 fans at $32 is the best average ticket of the tour by a wide margin, and the $192,000 gate is well clear of every night but Sendai and Kanazawa combined. The $12,000 in merchandise, at $2 a head, is the first merch figure logged for this promotion all tour. Whatever is driving the walk-up here, Nagoya is now the highest average ticket of the Summer Action Series and worth a look before the tour routes future dates."]]}, "ajpw-diary-slinger-0711": {"p": "ajpw", "series": "diary", "by": "Richard Slinger", "date": "1991-07-11", "place": "Nagoya, heading toward Hiroshima", "kicker": "From the Road · Nagoya, July 11", "title": "Across the Ring from Jumbo", "dek": "Richard Slinger found out two hours before bell time that he was in a six-man against Jumbo Tsuruta. Then he ate the knee.", "factTitle": "The Night", "facts": [["Show", "Summer Action Series, Night 6, Nagoya"], ["Match", "Jumbo, Taue & Kobashi d. Williams, Gordy & Slinger"], ["Finish", "Jumbo Knee on Slinger, 10:29"], ["Rating", "***"]], "body": [["p", "Tonight I got pinned by the Triple Crown Champion of All Japan, and I think it might be the best thing that's happened to me since I got off the plane."], ["p", "Nobody told me until about two hours before bell time that I was in a six-man with Jumbo Tsuruta, Akira Taue and Kenta Kobashi against the Miracle Violence Connection. I thought they meant I was working with Williams and Gordy. Then the sheet got handed around again and I saw my name on the other side of it from them, across the ring from Jumbo-san. I went and found a quiet hallway and just breathed for a minute."], ["p", "He didn't say much to me before the match. He didn't have to. When you're in the ring with him you can feel exactly how much is actually happening versus how much he's letting happen, and he let me get in a lot more than I expected. I got a dropkick on Gordy that the building actually came up for. Then with about ten minutes gone, Jumbo caught me with the knee and that was that. I've watched a lot of guys eat that knee. Now I know what it feels like from the inside, and I can tell you every one of them earned their paycheck."], ["p", "Williams found me after and just said, \"Good, kid.\" Two words from Dr. Death is worth more to me right now than a signed contract."], ["p", "Riding the bus to Hiroshima now with my knee wrapped in ice and my notes from tonight's match half-written in the dark. Ogawa's a few seats up, still going on about the tag match, still convinced he and Inoue should have walked out with the belts. He might be right. He's not wrong very often."], ["p", "Two nights off before Hiroshima. I'm going to spend one of them writing my mother about getting in the ring with Jumbo Tsuruta, and I'm going to leave out the part where he pinned me in ten and a half minutes."]]}, "ajpw-champions-hold-the-line": {"p": "ajpw", "kicker": "Summer Action Series Report · Nagoya, July 11", "title": "Champions Hold the Line in Nagoya", "dek": "Misawa and Kawada turn back Rude and Abdullah, Can-Am Express survive Ogawa and Inoue, and Jumbo's army sends a message.", "by": "All Japan Pro Wrestling", "date": "1991-07-11", "body": [["p", "Both sets of champions walked out of the Aichi Prefectural Gymnasium still champions on Thursday night, but neither title match came easy, and the undercard left at least one young American with a story he will be telling for years."], ["p", "In the main event, World Tag Team Champions Mitsuharu Misawa and Toshiaki Kawada turned back the most dangerous team they have faced all tour. Rick Rude and Abdullah the Butcher gave the champions twenty-three minutes of chaos, with Abdullah going to the eyes more than once and Rude working Kawada's leg at every opportunity. It was Misawa who found the opening, catching Rude with the Running Elbowsmash to retain the titles. Abdullah was still arguing with the referee as the champions' music played."], ["p", "The All Asia Tag Team Championship stayed with Can-Am Express, but Yoshinari Ogawa and Masao Inoue made them work for every minute of it. Ogawa in particular has been the story of this tour, and he looked every bit like tomorrow's champion before Dan Kroffat finally silenced him with a moonsault bodyblock. Doug Furnas and Dan Kroffat retain, but the challengers left Nagoya with the crowd fully behind them."], ["h", "Jumbo's Army Sends A Message"], ["p", "Triple Crown Champion Jumbo Tsuruta did not wrestle alone tonight. With Akira Taue and Kenta Kobashi at his side, Jumbo faced down the Miracle Violence Connection of Steve Williams and Terry Gordy, with young Richard Slinger rounding out the opposing side. It did not go well for Slinger. Jumbo finished him with the Jumbo Knee in just over ten minutes, a clear reminder to Williams and to everyone else in the building of exactly who still runs this tour."], ["h", "Two Falls, No Answer For Ace"], ["p", "Dean Malenko needed the full allotment to settle things with Johnny Ace, taking the first fall with a side suplex before Ace was counted out chasing the win in the second. The Malenkos have now beaten every junior AJPW has thrown at them this July, and there is no name left on the tour that looks like a real test."], ["h", "Around The Ring"], ["p", "Too Cold Scorpio opened the show with a Flying Scorpio Splash to put away Rusher Kimura. And in a tour that has mostly kept its two toughest gaijin apart from trouble, Stan Hansen and Dan Spivey fought the British Bulldogs to a double countout, with Dynamite Kid and Hansen trading shots well after the bell had stopped meaning anything."], ["p", "The tour rolls on to Hiroshima on July 13."]], "factTitle": "Nagoya Results", "facts": [["World Tag", "Misawa & Kawada retain (Misawa pins Rude)"], ["All Asia Tag", "Can-Am Express retain"], ["Six-man", "Jumbo pins Slinger (Jumbo Knee)"], ["Next", "Hiroshima, July 13"]]}, "ajpw-kawada-leaving": {"p": "ajpw", "news": 1, "by": "Tokyo Report", "date": "1991-07-13", "kicker": "AJPW · Breaking news", "title": "Kawada Is Leaving All Japan", "dek": "Toshiaki Kawada gave notice in Hiroshima. His last date is Okayama on Monday, with the World Tag titles on the line, and the dressing room says he's headed to New Japan.", "factTitle": "The Exit", "facts": [["Notice", "After Hiroshima, July 13"], ["Last AJPW date", "Okayama, July 15"], ["On the line", "World Tag Team Titles (with Misawa)"], ["Rumored next stop", "New Japan"]], "body": [["p", "Toshiaki Kawada is leaving All Japan Pro Wrestling. He gave the office his notice after the Six-Man Tag Special in Hiroshima on July 13, and his last date is Monday night in Okayama, where he and Mitsuharu Misawa defend the World Tag Team Championship against the Miracle Violence Connection."], ["p", "The reason, according to people close to him, is the USWA. Kawada had been working Memphis dates this year, and he believes the office made him give that up. He is said to be angry about it. He won't be going back to Memphis either: the USWA has no plans to bring him back, because it wants to keep its working relationship and talent exchange with All Japan."], ["p", "So where does he go? The rumor in the dressing room is New Japan. Nothing has been signed that anyone will talk about, but the timing fits. New Japan's Summer Crush tour has five dates left, from Fukuoka on July 18 to the Sumo Hall finale on July 30."], ["p", "Kawada leaves a big hole. He is half of the World Tag Team Champions, he took Jumbo Tsuruta to the limit for the Triple Crown in Chiba on July 3, and he was booked for the rest of the tour: against Rick Rude in Kumamoto, against Misawa in Yokohama, and with Kenta Kobashi for the All Asia Tag titles at the Budokan. All of that has to be rebooked, and the tag belts have to be settled first."], ["p", "He worked the Hiroshima main event as if nothing were wrong, teaming with Misawa and Kobashi to beat Steve Williams, Terry Gordy and Richard Slinger. Afterward he sat alone in the dressing room for a long time."], ["p", "Monday in Okayama is the last time to see him in an All Japan ring."]]}, "ajpw-observer-hiroshima-0713": {"p": "ajpw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-13", "region": "Tokyo Report", "kicker": "AJPW · Hiroshima Sun Plaza, July 13", "title": "Hiroshima: The Young Boys Steal It, and Kawada Gives Notice", "dek": "Masao Inoue has the opener of the tour, Funk and the Malenkos go ****3/4, and the biggest news happens in the dressing room.", "factTitle": "Match observations", "facts": [["Venue", "Hiroshima Sun Plaza"], ["City", "Hiroshima, Japan"], ["Date", "July 13, 1991 (Summer Action Series, Night 7)"], ["Attendance", "3,800"], ["Average ticket", "$25.00"], ["Gate", "$95,000.00"], ["Card", "***"]], "body": [["p", "Night 7 of the Summer Action Series rated ***, a quarter of a star under Nagoya, but the overall number hides a very uneven card. Three matches went **** or better, which is as good a night of wrestling as All Japan has had on this tour, and the two everyone will talk about were in the first half. The main event was fine. The brawl in the middle was nothing."], ["p", "The opener is the story. Masao Inoue, 21 years old and two nights removed from losing an All Asia Tag title match in Nagoya, pinned Billy Joe Travis with a roll-up in 8:22 and got ****1/4. Nobody books an opener expecting that. Inoue is a young boy who carries bags and sets up the ring, and he just had the best opener of the tour by a mile. Travis deserves some of the credit too."], ["p", "Too Cold Scorpio then beat Johnny Ace with the Flying Scorpio Splash in 10:25 for ****. That evens them at a win apiece after Ace ended Scorpio's streak in Kanazawa, and the two of them should be kept together. Ace has now lost twice in three nights, but he has looked good in both."], ["p", "The match of the night, and the best match of the tour so far, was the six- man: Dory Funk Jr. and the Malenkos over Yoshinari Ogawa, Tsuyoshi Kikuchi and Akira Taue at ****3/4. It went 16:22 and ended with Joe Malenko making Kikuchi submit to the Final Lesson. The plan called for a pin, but the submission works better for the Malenkos' act. Ogawa's small package on Joe, the near fall that sets up their singles match in Okayama on Monday, got the biggest reaction of the night. Funk, at 50, was right there with the younger men. Dean Malenko was also in the co-best match in Nagoya two nights ago."], ["p", "The worst thing on the show was the Abdullah tag, which went DUD in 8:07. Rusher Kimura and Masanobu Fuchi won by disqualification, which was the plan, and Abdullah's post-match fork attack on Kimura was the angle that mattered. What wasn't in the plan was Joe Malenko coming down and interfering against Kimura before he'd even wrestled his own match. The office now has a choice: write it off, or make something of the Malenkos siding with the foreign heels. Both Malenkos have been booked as self- appointed gatekeepers, so it isn't a stretch."], ["p", "The British Bulldogs beat the Fantastics in 12:11 at ***, with Dynamite pinning Fulton with the diving headbutt. Solid and forgettable."], ["p", "Jumbo's interview did what it needed to. He answered Williams, put Budokan on the table and made Monday's match with Kobashi sound like a test he's looking forward to."], ["p", "The main event rated ***, the same as the Jumbo six-man in Nagoya. Misawa pinned Terry Gordy with the Tiger Driver in 20:39, which is a stronger finish than Jumbo pinning Slinger on Thursday, and Williams wasn't pinned, so he goes to Budokan untouched. The stare-down with Misawa afterward, and Williams pointing at the Triple Crown poster, worked. The match itself never got going the way the six-man before it did. Three of the six men in it were Super Generation, and the best thing on the card was still the juniors."], ["p", "The business is fine but not special. 3,800 at $25 is $95,000, below the Nagoya number but above every other night of the tour except Nagoya. That makes $653,257 for seven nights, about $93,300 a night. No merchandise figure was reported."], ["p", "The real story of the night happened away from the ring. Toshiaki Kawada has given notice that he plans to leave All Japan. No date has been set, at least not one anyone is saying out loud. He worked the main event and did his job, but this changes a lot. Kawada is half of the World Tag Team Champions with Misawa. He's booked against Rick Rude in Kumamoto on Wednesday, against Misawa in Yokohama on July 23, and alongside Kobashi for the All Asia Tag title at Budokan on the 27th. If he's gone before the end of the tour, the belts have to be dealt with first, and the obvious way to do that is to give Misawa a new partner. Kobashi is right there. If he finishes the tour, the Misawa singles match in Yokohama becomes a farewell, and that's a better story than the handshake on the original sheet."], ["p", "Elsewhere tonight, Stan Hansen and Dan Spivey worked the USWA in Louisville instead of this card, and Rick Rude was on the WCW show in Greenville, South Carolina. He's back in Japan for Kumamoto on Wednesday, the night he's booked against Kawada."], ["p", "Okayama on Monday has Jumbo vs. Kobashi and Ogawa vs. Joe Malenko. After tonight, both matches matter more than they did this morning."]]}, "ajpw-diary-inoue-0713": {"p": "ajpw", "series": "diary", "by": "Masao Inoue", "date": "1991-07-13", "place": "Hiroshima Sun Plaza", "kicker": "From the Road · Hiroshima, July 13", "title": "Up at Seven Again", "dek": "The young boy who loads the ring truck has the best opener of the tour, then has to help drag Abdullah off Rusher Kimura.", "factTitle": "The Night", "facts": [["Show", "Summer Action Series, Night 7, Hiroshima"], ["Match", "Masao Inoue d. Billy Joe Travis"], ["Finish", "Roll-up, 8:22"], ["Rating", "****1/4"]], "body": [["p", "I was up at seven to load the ring truck, same as every morning on this tour. Nobody told me anything about tonight except that I was in the opener with Billy Joe Travis. That's normal. Young boys find out what they're doing when they find out."], ["p", "After Nagoya I didn't sleep well. Ogawa-san and I were so close against Can-Am Express, and then Kroffat came off the ropes and that was it. I kept seeing it in the dark. So tonight I just wanted to win something."], ["p", "Travis is a big man, and he's a lot stronger than he looks on the cards. He threw me around the ring for most of the eight minutes. I kept getting up. The crowd started clapping every time I got up, and I could hear it getting louder. When he went for his finish I slipped behind him and rolled him up, and the referee counted three. I didn't believe it until I heard the bell."], ["p", "Back in the dressing room, Fuchi-san told me it was a very good match. He doesn't say that."], ["p", "I didn't have time to enjoy it. Kimura-san and Fuchi-san were next against Abdullah and Kimala, and when Abdullah pulled out the fork, the young boys had to go in. I grabbed his arm and he just kept going. Three of us and he still wouldn't let go of Kimura-san. Joe Malenko had come down and gotten involved too, and I still don't know why. Abdullah looked straight at the camera on his way out with the fork in his hand. I washed my hands twice afterward."], ["p", "I watched the six-man from behind the curtain. Ogawa-san had Joe Malenko pinned. I was sure. Joe kicked out, and later he made Kikuchi-san quit in that hold. Ogawa-san didn't talk much afterward, but he gets Joe by himself on Monday. I think he's been waiting for that all tour."], ["p", "Jumbo-san did his interview in the back while I was carrying the water. He's so calm. When he raised his fist, the whole building shouted with him. I've never heard that from that close."], ["p", "The main event was the Super Generation. I carried Misawa-san's towel. When Misawa-san finished Gordy with the Tiger Driver, the building went crazy. Williams stood there afterward and pointed at Jumbo-san's poster like the match wasn't really over for him."], ["p", "Kawada-san was very quiet in the dressing room after the match. He sat by himself for a long time and didn't say much to anybody. I didn't ask. It isn't my place."], ["p", "Okayama is Monday. I have to be up at seven again."]]}, "ajpw-super-generation-answers": {"p": "ajpw", "kicker": "Summer Action Series Report · Hiroshima, July 13", "title": "Super Generation Answers Jumbo", "dek": "Misawa pins Gordy with the Tiger Driver, Jumbo finally speaks, and the Malenkos hold the wall in the match of the tour.", "by": "All Japan Pro Wrestling", "date": "1991-07-13", "body": [["p", "Two nights after Jumbo Tsuruta's side beat the Miracle Violence Connection and Richard Slinger in Nagoya, Mitsuharu Misawa's side got its turn against the same three men in Hiroshima. Misawa made sure his answer was louder."], ["p", "Misawa, Toshiaki Kawada and Kenta Kobashi went twenty minutes with Steve Williams, Terry Gordy and Slinger in the main event of the Six-Man Tag Special. Jumbo pinned the youngest man in the opposing corner on Thursday. Misawa went after the biggest. He caught Gordy, lifted him up and dropped him with the Tiger Driver for the three count at 20:39."], ["p", "Williams was never pinned, and he made sure everyone noticed. When the bell rang he stood in the middle of the ring with Misawa and neither man moved. Then Williams turned, found the Triple Crown poster hanging over the entrance and pointed at it. The message was for Jumbo, and Misawa was standing right there to hear it."], ["h", "Jumbo: \"We Find Out In The Ring\""], ["p", "Jumbo didn't wrestle tonight, but he finally spoke. With the three belts over his shoulder, the champion answered Williams for the first time since the Doctor called him out in Kanazawa. If Williams wants Budokan, Jumbo said, he'll have Budokan. But first comes Monday in Okayama, and Kenta Kobashi. He finished with his fist in the air, and the Sun Plaza shouted it back at him."], ["h", "The Gatekeepers Hold Again"], ["p", "The match of the night came in the middle of the card. Dean and Joe Malenko teamed with Dory Funk Jr. against Yoshinari Ogawa, Tsuyoshi Kikuchi and Akira Taue, and for sixteen minutes nobody in the building sat down. Ogawa came closest to an upset when he rolled Joe up in a small package and had the referee's hand coming down for three before Joe kicked out. It didn't last. Joe trapped Kikuchi in the Final Lesson and Kikuchi had to submit at 16:22. The Malenkos are still the wall, but Ogawa has now been within a fraction of a second of beating one of them, and he gets Joe on his own in Okayama on Monday."], ["h", "The Fork Comes Out Again"], ["p", "Rusher Kimura and Masanobu Fuchi won their match with Abdullah the Butcher and Giant Kimala II, but nobody will remember the result. Joe Malenko came down to ringside and went after Kimura, and Abdullah pulled out the fork, the same fork that put Giant Baba on a stretcher in Chiba. The referee threw it out at 8:07. Abdullah wouldn't stop. It took the young boys to drag him off Kimura, and on his way out Abdullah held the fork up to the hard camera. Misawa vs. Abdullah at Budokan just got a little more personal."], ["h", "Around The Ring"], ["p", "Masao Inoue opened the show with the best win of his young career, rolling up Billy Joe Travis at 8:22 two nights after coming up short in the All Asia Tag title match in Nagoya. Too Cold Scorpio evened his account with Johnny Ace, who handed him his first loss in Kanazawa, by hitting the Flying Scorpio Splash at 10:25. And the British Bulldogs beat the Fantastics when Dynamite Kid came off the top with the diving headbutt on Bobby Fulton at 12:11."], ["p", "The tour moves on to Okayama on Monday: Jumbo Tsuruta vs. Kenta Kobashi, and Yoshinari Ogawa vs. Joe Malenko."]], "factTitle": "Hiroshima Results", "facts": [["Main", "Misawa pins Gordy (Tiger Driver)"], ["Match of the night", "Funk & Malenkos d. Ogawa, Kikuchi & Taue"], ["Interview", "Jumbo: \"We find out in the ring\""], ["Next", "Okayama, July 15"]]}, "ajpw-mvc-take-the-gold": {"p": "ajpw", "kicker": "Summer Action Series Report · Okayama, July 15", "title": "Miracle Violence Takes the Gold", "dek": "Gordy powerbombs Kawada for the World Tag titles on his last night, Jumbo holds off Kobashi, and the Fantastics earn a Budokan shot.", "by": "All Japan Pro Wrestling", "date": "1991-07-15", "factTitle": "Okayama Results", "facts": [["Main", "MVC d. Misawa & Kawada, new World Tag Champions"], ["Triple Crown", "Jumbo d. Kobashi"], ["Budokan shot", "Fantastics d. Can-Am (non-title)"], ["Farewell", "Toshiaki Kawada's last AJPW date"], ["Next", "Kumamoto, July 17"]], "body": [["p", "Toshiaki Kawada's last night in All Japan ended with the World Tag Team Championship around someone else's waist."], ["p", "Mitsuharu Misawa and Kawada defended against Steve Williams and Terry Gordy in the main event at the Okayama Budokan, and for twenty minutes the champions gave everything they had. Kawada kicked Williams until his shins were red. Misawa hit the elbows. It wasn't enough. At 20:21 Gordy caught Kawada, lifted him up and drove him down with a powerbomb, and the referee counted three. The Miracle Violence Connection are the new World Tag Team Champions."], ["p", "Williams and Gordy took the belts and left. Misawa stayed on his knees in the ring. Kawada got up, looked at his partner for a long moment, and walked to the back by himself. He didn't take the microphone. He didn't come back out."], ["p", "One match earlier, Jumbo Tsuruta put the Triple Crown on the line against Kenta Kobashi. Kobashi took the Jumbo Knee and kicked out. He took it again and kicked out again, and the Okayama crowd was on its feet. Jumbo finally ended it with a backdrop driver at 18:55. Jumbo keeps the title, and Steve Williams gets him at the Nippon Budokan on July 27."], ["p", "The Fantastics earned a title shot of their own. Tommy Rogers rolled up Dan Kroffat at 17:53 of a non-title match with the All Asia Tag Team Champions, and Bobby Fulton and Rogers will challenge the Can-Am Express at Budokan."], ["p", "Yoshinari Ogawa beat Joe Malenko with a small package at 15:26, even with Dean Malenko getting involved from the floor. There was no handshake. Akira Taue dropped Davey Boy Smith with the nodowa otoshi. Dynamite Kid beat Too Cold Scorpio with the diving headbutt in a fight that had the building roaring, and Tsuyoshi Kikuchi and Masao Inoue, the young boys who stole Hiroshima, did it again by beating Richard Slinger and Billy Joe Travis."], ["p", "Misawa has a new partner coming. The tour moves to Kumamoto on Wednesday."]]}, "ajpw-observer-okayama-0715": {"p": "ajpw", "series": "observer", "news": 1, "by": "Wrestling Observer Newsletter", "date": "1991-07-15", "region": "Tokyo Report", "kicker": "AJPW · Okayama Budokan, July 15", "title": "Okayama: Kawada Goes Out With the Belts, and the Best Card of the Tour", "dek": "Miracle Violence wins the World Tag titles on Kawada's last night, Jumbo and Kobashi go ****1/4, and the smallest house of the tour sees the best show.", "factTitle": "Match observations", "facts": [["Venue", "Okayama Budokan"], ["City", "Okayama, Japan"], ["Date", "July 15, 1991 (Summer Action Series, Night 8)"], ["Attendance", "2,100"], ["Average ticket", "$20.00"], ["Gate", "$42,000.00"], ["Card", "***3/4"], ["Match of the night", "Three at ****1/4"]], "body": [["p", "Night 8 of the Summer Action Series drew 2,100 to the Okayama Budokan, which holds 3,000, at a $20 average for a $42,000 gate. That's the smallest gate and the cheapest ticket of the tour, the first house under $50,000, on a Monday in a regional town. It was also the best card of the tour at ***3/4, with four matches at **** or better. The people who stayed home missed a great show."], ["p", "The story is Toshiaki Kawada. This was his last date with All Japan after giving notice in Hiroshima, and the office took the World Tag titles off him and Misawa on the way out. The Miracle Violence Connection won them when Gordy powerbombed Kawada in 20:21. ****. Kawada worked like a man who wanted everyone to remember what they're losing, and then he walked out alone and didn't come back for the curtain call. The dressing room still has him going to New Japan. Nothing is signed that anyone will confirm."], ["p", "Losing Kawada costs All Japan more than one tag team. Super Generation was three men, and now it's Misawa and Kobashi, who is 24. The plan is for Misawa to name Kobashi his new partner in Kumamoto and for them to challenge Williams and Gordy in Yokohama on 7/23. Kobashi's performance tonight is the best argument for it."], ["p", "Tsuyoshi Kikuchi & Masao Inoue beat Richard Slinger & Billy Joe Travis in 11:59 when Kikuchi pinned Slinger with a bridging back suplex. ****1/4. For the second straight show the opener was one of the best matches on the card. Inoue, 21, was in the ****1/4 opener in Hiroshima too. These two need to be moved up the card."], ["p", "Dynamite Kid pinned Too Cold Scorpio with the diving headbutt in 12:17. ****1/4. Dynamite is the best he's looked on the tour, and Scorpio has had **** matches with Ace and now Dynamite in back-to-back shows."], ["p", "Akira Taue pinned Davey Boy Smith with the nodowa otoshi in 10:16. ***1/4. Davey's last date is Budokan, so expect the Bulldogs to keep losing on the way out."], ["p", "Yoshinari Ogawa beat Joe Malenko with a small package in 15:26. ***. Dean Malenko interfered, which wasn't planned, and Ogawa won anyway. That's two shows in a row with a Malenko getting involved in someone else's match. Dean still has no challenger for the World Junior picture before Budokan, and Ogawa just beat his brother."], ["p", "The Fantastics beat the Can-Am Express in a non-title match in 17:53 when Rogers rolled up Kroffat. ***. That earns them the All Asia Tag title match at Budokan."], ["p", "Jumbo Tsuruta beat Kenta Kobashi with a backdrop driver in 18:55. ****1/4. It was billed as a Triple Crown defense, which it wasn't originally meant to be, and it was terrific. Kobashi kicked out of the knee twice and the crowd bought every near fall. Jumbo goes to Budokan against Williams having beaten Kawada and Kobashi on this tour, which is exactly where the office wants him."], ["p", "Bottom line: a small house, a great show and a real loss. The tour's gates are at $695,257 through eight nights. Without Kawada, Yokohama and Budokan will lean on Misawa and Kobashi."]]}, "ajpw-diary-kawada-0715": {"p": "ajpw", "series": "diary", "by": "Toshiaki Kawada", "date": "1991-07-15", "place": "Okayama Station", "kicker": "From the Road · Okayama, July 15", "title": "I Didn't Look Back", "dek": "Toshiaki Kawada on his last night in All Japan, the powerbomb that took the belts, and the walk to the back.", "factTitle": "The Night", "facts": [["Show", "Summer Action Series, Night 8, Okayama"], ["Match", "MVC d. Misawa & Kawada (World Tag)"], ["Finish", "Gordy powerbombs Kawada, 20:21"], ["Rating", "****"], ["After", "Left All Japan"]], "body": [["p", "I'm writing this on the platform. The last train to Osaka leaves in twenty minutes and my bag is next to me. Everything I own in this business fits in it."], ["p", "Baba-san didn't come to Okayama. I didn't expect him to. The office sent the order through the boys this afternoon: Miracle Violence wins, Gordy pins me. I said fine. It's their belt. It was always their belt."], ["p", "I gave Williams everything tonight. I kicked him until he stopped smiling. I wanted the people in that building to remember who was in the ring when the titles changed. Gordy's powerbomb is the heaviest thing in Japan. I heard the count from very far away."], ["p", "Misawa was on his knees after. I looked at him for a long time. We've been together since we were the boys carrying Jumbo's bags. He didn't say anything and neither did I. There wasn't anything to say that we hadn't said already in the dressing room in Hiroshima."], ["p", "So I walked to the back alone. The young boys were lined up in the hallway the way they line up for the big names, and Kikuchi bowed so low I thought he'd fall over. Inoue was crying. I told him to stop, that he had a show on Wednesday."], ["p", "People will say I'm going to New Japan. Let them. Tonight I'm going to Osaka, and tomorrow I'll sleep as long as I want for the first time since June."], ["p", "The train is coming. I'm not going to look back at the city."]]}});

CONTRACTS.ajpw = {"basis": "Per tour", "unit": "per tour", "revenue": "Summer Action Series: $695,257 from the first eight nights (about $87K a night). Fourteen nights puts the full tour at roughly $1.2M.", "target": "Tour payroll at about 35% of the tour gate.", "how": "One flat fee per tour, paid at the end of the tour. A wrestler who misses nights (shuttling to the USWA or WCW, or injured) is paid that share of the fee for the nights he worked. Fees below are for a full-length tour of about 14 nights. Giant Baba owns the company and is not on the scale. Managers and announcers are on the same scale. The Nippon TV booth is paid by the network, not the promotion.", "classes": [], "rows": [["A", "Jumbo Tsuruta", 30000, "Triple Crown Champion"], ["A", "Stan Hansen", 30000, "Top gaijin, also USWA"], ["A", "Mitsuharu Misawa", 22000, "World Tag Champion"], ["A", "Steve Williams", 22000, ""], ["A", "Terry Gordy", 22000, ""], ["B", "Rick Rude", 18000, "Also WCW"], ["B", "Davey Boy Smith", 15000, ""], ["B", "Toshiaki Kawada", 14000, "Leaving after Okayama 7/15. Paid per appearance instead of the tour fee: $1,000 a night (Sean, 2026-11-11)"], ["B", "Kenta Kobashi", 12000, ""], ["B", "Akira Taue", 12000, ""], ["B", "Dynamite Kid", 12000, "Retires 12/6"], ["B", "Abdullah the Butcher", 12000, "Also WCW"], ["B", "Dory Funk Jr.", 12000, ""], ["B", "Dan Spivey", 12000, "Also USWA"], ["C", "Doug Furnas", 10000, "All Asia Tag Champion"], ["C", "Dan Kroffat", 10000, "All Asia Tag Champion"], ["C", "Bobby Fulton", 8000, ""], ["C", "Tommy Rogers", 8000, ""], ["C", "Masanobu Fuchi", 8000, ""], ["C", "Dean Malenko", 7000, ""], ["C", "Joe Malenko", 7000, ""], ["C", "Johnny Ace", 6000, ""], ["C", "Rusher Kimura", 6000, ""], ["D", "Haruka Eigen", 5000, "Injured, back 7/17"], ["D", "Giant Kimala II", 5000, ""], ["D", "Tsuyoshi Kikuchi", 5000, ""], ["D", "Too Cold Scorpio", 5000, ""], ["D", "Yoshinari Ogawa", 4000, ""], ["D", "Billy Joe Travis", 4000, ""], ["E", "Masao Inoue", 3000, ""], ["E", "Richard Slinger", 3000, ""], ["O", "Kero Tanaka", 3000, "Ring announcer"], ["O", "TBD: second ring announcer / MC", 2000, "Name to be set"]], "total": 354000, "check": "Full-tour fees total $354,000: about 35% of a $1.0M tour."};

FINANCE.ajpw = {"period": "Per tour", "payBasis": "Per tour", "rows": [{"d": "1991-07-01", "show": "Tokyo · Summer Action Series, Night 1", "cls": "", "gate": 51992, "payroll": null, "note": ""}, {"d": "1991-07-03", "show": "Chiba · Night 2", "cls": "", "gate": 71765, "payroll": null, "note": ""}, {"d": "1991-07-05", "show": "Sendai · Night 3", "cls": "", "gate": 87500, "payroll": null, "note": ""}, {"d": "1991-07-07", "show": "Niigata · Night 4", "cls": "", "gate": 67500, "payroll": null, "note": ""}, {"d": "1991-07-09", "show": "Kanazawa · Night 5 (Nippon TV)", "cls": "", "gate": 87500, "payroll": null, "note": ""}, {"d": "1991-07-11", "show": "Nagoya · Night 6", "cls": "", "gate": 192000, "merch": 12000, "payroll": null, "note": "6,000 at $32"}, {"d": "1991-07-13", "show": "Hiroshima · Night 7", "cls": "", "gate": 95000, "payroll": null, "note": "3,800 at $25 (onesheet)"}, {"d": "1991-07-15", "show": "Okayama · Night 8", "cls": "", "gate": 42000, "payroll": null, "note": "2,100 at $20 (onesheet)"}], "fixed": ["Summer Action Series tour fees ($340,000) plus Kawada per appearance (6 nights × $1,000)", 346000], "note": "Tour fees are paid at the end of the tour (7/27 Budokan). Kawada left after Okayama 7/15 and is paid per appearance instead, $1,000 a night (his $14,000 fee ÷ 14 nights): 6 nights worked. Gates through night 8."};

SITES.ajpw = {"base": "https://shovan123-lang.github.io/AJPW/HTML/", "arch": [["Summer Action Series 1991", [["Night 1 · Tokyo, Korakuen Hall · 7.1", "SUMMER_A"], ["Night 2 · Chiba Port Arena · 7.3", "CHIBA__C"], ["Night 3 · Sendai City Gym · 7.5", "SENDI__S"], ["Night 4 · Niigata City Gym · 7.7", "NIGATA__"], ["Night 5 · Kanazawa, Ishikawa Gym · 7.9", "KANAZAWA"], ["Night 6 · Nagoya, Aichi Gym · 7.11", "NAGOYA__"], ["Night 7 · Hiroshima, Sun Plaza · 7.13", "HIROSHIM"]]]], "label": "Summer Action Series show pages"};
